mapper.sql:
SELECT class_id, class_name, grade, grade_index, class_no, head_teacher, capacity FROM class_info
grade = #{grade}
AND 1 = 0
AND class_id IN #{cid}
ORDER BY grade_index, class_no

mapper.select:
WITH totals AS ( SELECT s.id AS student_id, COALESCE(SUM(sc.score), 0) AS total FROM student s LEFT JOIN student_score sc ON sc.student_id = s.id GROUP BY s.id ), ranked AS ( SELECT s.id, s.sid, s.name, s.class_id, t.total, ROW_NUMBER() OVER (PARTITION BY s.class_id ORDER BY t.total DESC, s.sid ASC) AS rn FROM student s JOIN totals t ON t.student_id = s.id WHERE s.status = '在读' ) SELECT class_id, id, sid, name, total FROM ranked WHERE rn = 1
AND 1 = 0
AND class_id IN #{cid}
